INSERT INTO public.chapters (book_id,chapter_number,title,slug,description,source_page,display_order) SELECT b.id,x.n::integer,x.title,x.slug,x.description,x.page::integer,x.n::integer FROM (VALUES ('65','দক্ষিণ এশিয়ার দেশসমূহ','south-asia-country-profiles','Source-preserved Afghanistan, Bhutan, Nepal, Sri Lanka, and Maldives material.','539')) x(n,title,slug,description,page) JOIN public.books b ON b.title='Jubayer''s GK' WHERE NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.book_id=b.id AND c.slug=x.slug);
