('south-asia-country-profiles','ভুটান','bhutan-reference','540','2'),
('south-asia-country-profiles','নেপাল','nepal-reference','541','3'),
('south-asia-country-profiles','শ্রীলঙ্কা','sri-lanka-reference','542','4'),
('south-asia-country-profiles','মালদ্বীপ','maldives-reference','543','5')) x(chapter_slug,title,slug,page,ord) JOIN public.chapters c ON c.slug=x.chapter_slug AND c.book_id=(SELECT id FROM public.books WHERE title='Jubayer''s GK' LIMIT 1) WHERE NOT EXISTS (SELECT 1 FROM public.topics t WHERE t.chapter_id=c.id AND t.slug=x.slug);
